{
  "name": "opencode-headroom-plugin",
  "version": "1.0.0",
  "description": "OpenCode v2 plugin that transparently compresses large tool results via Headroom at the message level — works with any provider, including AWS Bedrock.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "headroom",
    "llm",
    "context-compression",
    "token-optimization",
    "aws-bedrock"
  ],
  "type": "module",
  "license": "MIT",
  "author": "pietro partescano <goldfix@users.noreply.github.com>",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/goldfix/opencode-headroom-plugin.git"
  },
  "bugs": {
    "url": "https://github.com/goldfix/opencode-headroom-plugin/issues"
  },
  "homepage": "https://github.com/goldfix/opencode-headroom-plugin#readme",
  "exports": {
    ".": "./src/index.js"
  },
  "files": [
    "index.js",
    "src",
    "scripts",
    "assets"
  ],
  "scripts": {
    "test": "node --test test/",
    "plugin:install": "bash scripts/install.sh",
    "plugin:uninstall": "bash scripts/uninstall.sh"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.19"
  },
  "engines": {
    "node": ">=20.3"
  }
}
